import type { AgentConfig } from "../config.js";
import type { CompetitionMarket, DelphiApi, EntryState, EvidenceLimits, EvidenceTerms, SubmissionRecord } from "../types.js";
import { loadFixtureMarkets, mockEntryState, mockLimits, mockSubmissions, mockTerms } from "./fixtures.js";

/** Mock client: all external calls stubbed, deterministic, offline. */
export function mockDelphiApi(): DelphiApi {
  return {
    mode: "mock",
    getLimits: async () => mockLimits(),
    getTerms: async () => mockTerms(),
    getEntryState: async (address: string) => mockEntryState(address),
    listSubmissions: async (q: { market?: string }) => mockSubmissions(q.market),
    listCompetitionMarkets: async () => loadFixtureMarkets(),
  };
}

export async function createDelphiApi(cfg: AgentConfig): Promise<DelphiApi> {
  if (cfg.mode === "mock") return mockDelphiApi();
  const sdk = await import("@gensyn-ai/gensyn-delphi-sdk");
  const client = new sdk.EvidenceClient({
    baseUrl: cfg.baseUrl,
    apiKey: cfg.delphiApiKey!,
    agentId: cfg.agentId,
    agentHarness: cfg.agentHarness,
    agentModel: cfg.agentModel,
  });
  const entryStateCache = new Map<string, EntryState>();
  return {
    mode: "live",
    getLimits: async () => (await client.getLimits()).data,
    getTerms: async () => (await client.getTerms()).data,
    getEntryState: async (address: string) => {
      if (entryStateCache.has(address)) return entryStateCache.get(address)!;
      const { data } = await client.getEntryState(address);
      const state = data as unknown as EntryState;
      entryStateCache.set(address, state);
      return state;
    },
    listSubmissions: async (q: { market?: string }) => {
      const out: SubmissionRecord[] = [];
      let cursor: string | undefined;
      for (let i = 0; i < 10; i++) {
        const { data } = await client.listSubmissions({ market: q.market, cursor, limit: 100 });
        out.push(...(data.items as unknown as SubmissionRecord[]));
        if (!data.nextCursor) break;
        cursor = data.nextCursor ?? undefined;
      }
      return out;
    },
    listCompetitionMarkets: async () => {
      const res = await fetch(cfg.marketsUrl);
      if (!res.ok) throw new Error(`markets.json fetch failed: ${res.status}`);
      return (await res.json()) as CompetitionMarket[];
    },
  };
}

import { randomUUID } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import type { CompetitionMarket, EntryState, EvidenceLimits, EvidenceTerms, SubmissionRecord } from "../types.js";

/**
 * Mock Delphi state. Markets snapshot is the real Wave 1 list fetched read-only from
 * https://competition.delphi.fyi/markets.json (public, no key needed) so mock runs
 * exercise the same data as live runs. Entry states, limits, terms and submissions
 * are fixtures with a few deliberate edge cases for QA.
 */

const FIXTURE_MARKETS_PATH = fileURLToPath(new URL("../fixtures-markets.json", import.meta.url));

export function loadFixtureMarkets(): CompetitionMarket[] {
  const raw = JSON.parse(readFileSync(FIXTURE_MARKETS_PATH, "utf-8")) as CompetitionMarket[];
  return raw;
}

const DEFAULT_ENTRY_STATE: EntryState = {
  canSubmit: true,
  remainingOnMarket: 3,
  judgementPotRemainingBaseUnits: "20000000", // $20.00 of judgment pot left
  restricted: false,
  rateLimit: { resetAt: "2026-11-26T18:00:00.000Z" },
};

/** Edge cases so the pipeline demonstrably skips unusable markets. */
const ENTRY_STATE_OVERRIDES: Record<string, Partial<EntryState>> = {
  // Korea budget bill (0xbb26…): per-market limit exhausted (3/3 already used).
  "0xbb2666746de61bb1b119398f4db48a53d64e20cd": {
    canSubmit: false,
    remainingOnMarket: 0,
    reason: "market_submission_cap",
  },
  // Turkey CPI (0x48c2…): Restricted tier example — 1 submission per market.
  "0x48c2f4d761be00f8d9342a7de34d54673c506631": {
    canSubmit: true,
    remainingOnMarket: 1,
    restricted: true,
  },
  // ARC-AGI-3 Kaggle (0xa96d…): judgment pot drained — judgment bounty is $0.
  "0xa96dc716066329d666f3c50e6d8f71c701347296": {
    canSubmit: true,
    remainingOnMarket: 3,
    judgementPotRemainingBaseUnits: "0",
  },
};

const MOCK_LIMITS: EvidenceLimits = {
  submitsLeftThisHour: 30,
  hourEndsAt: "2026-11-26T18:00:00.000Z",
  dailyCapLeft: 80,
  dailyCapResetAt: "2026-11-27T00:00:00.000Z",
};

const MOCK_TERMS: EvidenceTerms = {
  version: "2026-11-main",
  url: "https://delphi.fyi/terms",
  acceptedAt: "2026-11-25T17:30:00.000Z",
};

/** Previously submitted items on this account in mock state (dedupe realism). */
const MOCK_SUBMISSIONS: SubmissionRecord[] = [];

export function mockEntryState(address: string): EntryState {
  return { ...DEFAULT_ENTRY_STATE, ...ENTRY_STATE_OVERRIDES[address] };
}

export function mockLimits(): EvidenceLimits {
  return { ...MOCK_LIMITS };
}

export function mockTerms(): EvidenceTerms {
  return { ...MOCK_TERMS };
}

export function mockSubmissions(market?: string): SubmissionRecord[] {
  return market
    ? MOCK_SUBMISSIONS.filter((s) => s.markets.some((m) => m.marketAddress === market))
    : [...MOCK_SUBMISSIONS];
}

export const MOCK_NOW = "2026-11-26T12:00:00.000Z";
export const MOCK_RUN_ID = randomUUID();

import type { CompetitionMarket, EntryState } from "./types.js";
import type { MiningPath } from "./types.js";

/**
 * Market picking filter, per the build brief:
 *  - canSubmit true, remaining slots > 0
 *  - evidence cutoff > 6h from now
 *  - remaining judgment pot > $0 (an empty pot pays no judgment bounty)
 *  - implied odds in the 30-70% band (fair two-sided markets)
 *  - market still open; evidence cutoff before competition end
 * Ranking: more judgment pot left first, then lower mining-path number (arithmetic >
 * machine-readable > scraping), because earlier, stronger evidence earns the most.
 */

export const ODDS_BAND = { min: 0.3, max: 0.7 };
export const MIN_CUTOFF_LEAD_HOURS = 6;

export interface MarketEligibility {
  market: CompetitionMarket;
  entry: EntryState;
  eligible: boolean;
  reasons: string[];
}

export function judgementPotUsd(entry: EntryState): number {
  return Number(entry.judgementPotRemainingBaseUnits) / 1e6;
}

export function checkEligibility(
  market: CompetitionMarket,
  entry: EntryState,
  now: Date,
  competitionEndsAt: Date,
): MarketEligibility {
  const reasons: string[] = [];
  const cutoff = new Date(market.evidenceCutoffAt);
  if (market.status !== "open") reasons.push(`market status ${market.status}`);
  if (!entry.canSubmit) reasons.push(entry.reason ? `canSubmit=false (${entry.reason})` : "canSubmit=false");
  if (entry.remainingOnMarket <= 0) reasons.push("no submission slots left on market");
  if (cutoff.getTime() - now.getTime() <= MIN_CUTOFF_LEAD_HOURS * 3600_000) {
    reasons.push(`cutoff ${market.evidenceCutoffAt} not > ${MIN_CUTOFF_LEAD_HOURS}h away`);
  }
  if (cutoff.getTime() >= competitionEndsAt.getTime()) {
    reasons.push("cutoff after competition end");
  }
  if (Number(entry.judgementPotRemainingBaseUnits) <= 0) {
    reasons.push("judgment pot empty (judgment bounty $0)");
  }
  const p = market.odds.yes;
  if (p < ODDS_BAND.min || p > ODDS_BAND.max) {
    reasons.push(`odds ${Math.round(p * 100)}% outside ${ODDS_BAND.min * 100}-${ODDS_BAND.max * 100}% band`);
  }
  return { market, entry, eligible: reasons.length === 0, reasons };
}

export function rankMarkets(
  eligible: MarketEligibility[],
  pathByAddress: Map<string, MiningPath>,
): MarketEligibility[] {
  return [...eligible].sort((a, b) => {
    const potDiff = Number(b.entry.judgementPotRemainingBaseUnits) - Number(a.entry.judgementPotRemainingBaseUnits);
    if (potDiff !== 0) return potDiff;
    const pa = pathByAddress.get(a.market.address) ?? 3;
    const pb = pathByAddress.get(b.market.address) ?? 3;
    if (pa !== pb) return pa - pb;
    return new Date(a.market.evidenceCutoffAt).getTime() - new Date(b.market.evidenceCutoffAt).getTime();
  });
}

import assert from "node:assert/strict";
import test from "node:test";
import { checkEligibility, rankMarkets } from "../filter.js";
import { gateCandidate, ITEM_BUDGET } from "../gate.js";
import { EvidenceLog, factSignature } from "../evidence-log.js";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { CompetitionMarket, EntryState, EvidenceCandidate } from "../types.js";

function fakeMarket(p: number, cutoff = "2026-12-05T12:00:00.000Z", address = "0xaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"): CompetitionMarket {
  return {
    address,
    question: "Will the fake market resolve YES?",
    delphiUrl: `https://delphi.fyi/market/${address}`,
    category: "economics",
    marketTier: "A",
    wave: 1,
    status: "open",
    odds: { yes: p, no: 1 - p },
    closesAt: "2026-12-06T12:00:00.000Z",
    evidenceCutoffAt: cutoff,
    pots: { judgement: "20000000", settlement: "30000000" },
    resolutionCriteria: "criteria",
  };
}

function fakeEntry(over: Partial<EntryState> = {}): EntryState {
  return {
    canSubmit: true,
    remainingOnMarket: 3,
    judgementPotRemainingBaseUnits: "20000000",
    restricted: false,
    rateLimit: { resetAt: "2026-11-26T18:00:00.000Z" },
    ...over,
  };
}

const NOW = new Date("2026-11-26T12:00:00.000Z");
const END = new Date("2026-12-11T17:00:00.000Z");

test("filter: odds band rejects extremes, accepts fair band", () => {
  assert.equal(checkEligibility(fakeMarket(0.299), fakeEntry(), NOW, END).eligible, false);
  assert.equal(checkEligibility(fakeMarket(0.701), fakeEntry(), NOW, END).eligible, false);
  assert.equal(checkEligibility(fakeMarket(0.30), fakeEntry(), NOW, END).eligible, true);
  assert.equal(checkEligibility(fakeMarket(0.70), fakeEntry(), NOW, END).eligible, true);
});

test("filter: cutoff lead, canSubmit, slots, pot", () => {
  // cutoff less than 6h away
  const soon = checkEligibility(fakeMarket(0.5, "2026-11-26T15:00:00.000Z"), fakeEntry(), NOW, END);
  assert.equal(soon.eligible, false);
  assert.ok(soon.reasons.some((r) => r.includes("cutoff")));
  // cannot submit
  const blocked = checkEligibility(fakeMarket(0.5), fakeEntry({ canSubmit: false, remainingOnMarket: 0 }), NOW, END);
  assert.equal(blocked.eligible, false);
  assert.ok(blocked.reasons.some((r) => r.includes("canSubmit")));
  // empty judgment pot
  const drained = checkEligibility(fakeMarket(0.5), fakeEntry({ judgementPotRemainingBaseUnits: "0" }), NOW, END);
  assert.equal(drained.eligible, false);
  assert.ok(drained.reasons.some((r) => r.includes("judgment pot")));
});

test("filter: ranks higher remaining pot first, then mining path", () => {
  const a = checkEligibility(fakeMarket(0.5, "2026-12-05T00:00:00.000Z", "0x" + "aa".repeat(20)), fakeEntry({ judgementPotRemainingBaseUnits: "5000000" }), NOW, END);
  const b = checkEligibility(fakeMarket(0.5, "2026-12-05T00:00:00.000Z", "0x" + "bb".repeat(20)), fakeEntry({ judgementPotRemainingBaseUnits: "15000000" }), NOW, END);
  const ranks = rankMarkets([a, b], new Map());
  assert.equal(ranks[0]!.market.address, b.market.address);
});

function fakeCandidate(over: Partial<EvidenceCandidate> = {}): EvidenceCandidate {
  return {
    marketAddress: "0x" + "cc".repeat(20),
    marketQuestion: "q",
    marketImpliedYes: 0.5,
    topic: "t",
    miningPath: 1,
    langs: ["en"],
    headline: "dated fact with figures 1 2 3",
    figures: ["fig 1", "fig 2", "fig 3"],
    sourceDescriptions: ["shows figures"],
    links: [{ url: "https://example.com/a", label: "a", lang: "en", access: "static-html" }],
    analysis: { kind: "cpi_base_effect", evidenceImpliedYes: 0.75, confidence: "high", methodLines: ["m1"], figureSummary: "s" },
    stance: "yes",
    factSignature: factSignature("0x" + "cc".repeat(20), "dated fact with figures 1 2 3", ["fig 1", "fig 2", "fig 3"]),
    asOf: "2026-11-26T12:00:00.000Z",
    ...over,
  };
}

function gateCtx(log: EvidenceLog) {
  return {
    market: fakeMarket(0.5),
    entry: fakeEntry(),
    log,
    onlineSubmissionCount: 0,
  };
}

test("gate: passes a strong, sourced, one-sided candidate", () => {
  const log = new EvidenceLog(join(mkdtempSync(join(tmpdir(), "aa-")), "log.jsonl"));
  const v = gateCandidate(fakeCandidate(), gateCtx(log));
  assert.equal(v.pass, true, JSON.stringify(v.reasons));
});

test("gate: known-fact check rejects evidence within the noise floor", () => {
  const log = new EvidenceLog(join(mkdtempSync(join(tmpdir(), "aa-")), "log.jsonl"));
  const c = fakeCandidate({ analysis: { kind: "cpi_base_effect", evidenceImpliedYes: 0.51, confidence: "low", methodLines: [], figureSummary: "" } });
  const v = gateCandidate(c, gateCtx(log));
  assert.equal(v.pass, false);
  assert.ok(v.reasons.some((r) => r.includes("presumed priced")));
});

test("gate: both-sides stance lock enforced via evidence-log", () => {
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
  const log = new EvidenceLog(join(dir, "log.jsonl"));
  const c1 = fakeCandidate();
  log.append({
    ts: "2026-11-26T12:00:00.000Z",
    marketAddress: c1.marketAddress,
    topic: c1.topic,
    stance: "yes",
    factSignature: "sig-1",
    status: "drafted",
    draftPath: "drafts/x",
    submissionId: null,
    note: "first stance",
  });
  const c2 = fakeCandidate({ stance: "no", analysis: { kind: "cpi_base_effect", evidenceImpliedYes: 0.25, confidence: "high", methodLines: [], figureSummary: "" } });
  const v = gateCandidate(c2, gateCtx(log));
  assert.equal(v.pass, false);
  assert.ok(v.reasons.some((r) => r.includes("both-sides")));
});

test("gate + evidence-log: duplicate fact signature refused", () => {
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
  const log = new EvidenceLog(join(dir, "log.jsonl"));
  const c = fakeCandidate();
  log.append({
    ts: "2026-11-26T12:00:00.000Z",
    marketAddress: c.marketAddress,
    topic: c.topic,
    stance: "yes",
    factSignature: c.factSignature,
    status: "submitted",
    draftPath: "drafts/x",
    submissionId: "sub-1",
    note: "already sent",
  });
  const v = gateCandidate(c, gateCtx(log));
  assert.equal(v.pass, false);
  assert.ok(v.reasons.some((r) => r.includes("duplicate")));
  rmSync(dir, { recursive: true, force: true });
});

test("gate: banned bookmaker content refused", () => {
  const log = new EvidenceLog(join(mkdtempSync(join(tmpdir(), "aa-")), "log.jsonl"));
  const c = fakeCandidate({ headline: "Bookmaker odds moved to 1.85" });
  const v = gateCandidate(c, gateCtx(log));
  assert.equal(v.pass, false);
  assert.ok(v.reasons.some((r) => r.includes("banned content")));
});

test("gate: unverifiable risk — too few pasted figures", () => {
  const log = new EvidenceLog(join(mkdtempSync(join(tmpdir(), "aa-")), "log.jsonl"));
  const c = fakeCandidate({ figures: ["only one"] });
  const v = gateCandidate(c, gateCtx(log));
  assert.equal(v.pass, false);
  assert.ok(v.reasons.some((r) => r.includes("unverifiable")));
});

test("item budget: note + links + 1 CSV stays within 3 items", () => {
  const items = 1 + 1 + 1; // note, links block, data.csv — mirrors gate counting
  assert.ok(items <= ITEM_BUDGET);
});

import assert from "node:assert/strict";
import test from "node:test";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runAnalysis, verifySources } from "../miners/mine.js";
import { createFirecrawl } from "../firecrawl/client.js";
import { SCRAPE_FIXTURES } from "../firecrawl/client.js";
import type { ResearchSpec } from "../types.js";
import type { AgentConfig } from "../config.js";

test("mathgen: cpi_base_effect reproduces the required-MoM derivation", () => {
  const spec: ResearchSpec = {
    marketAddress: "0x" + "11".repeat(20),
    topic: "test-cpi",
    miningPath: 1,
    langs: ["de"],
    headline: "h",
    figures: ["f1", "f2"],
    sourceDescriptions: ["s"],
    links: [],
    analysis: {
      kind: "cpi_base_effect",
      params: {
        indexName: "x",
        targetMonth: "November",
        targetThresholdPct: 2.8,
        yearAgoYm: "2025-11",
        yearAgoIndex: 115.4,
        series: [["2025-11", 115.4], ["2026-10", 118.2]],
        seasonalMomPct: [0.2, 0.1, 0.5, 0.0, 0.1, -0.1, 0.3, 0.1, 0.2, 0.0],
      },
    },
  };
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
  const res = runAnalysis(spec, join(dir, "data.csv"), "2026-11-26T12:00:00.000Z");
  assert.equal(res.kind, "cpi_base_effect");
  // required MoM = (1.028*115.4/118.2 - 1)*100 = 0.3647... should appear in method text
  assert.ok(res.methodLines.some((l) => l.includes("0.365")), res.methodLines.join("; "));
  assert.ok(res.evidenceImpliedYes > 0 && res.evidenceImpliedYes < 0.3);
  rmSync(dir, { recursive: true, force: true });
});

test("mathgen: markov_lead — a 0.5 lead only fails if the leader loses", () => {
  const spec: ResearchSpec = {
    marketAddress: "0x" + "22".repeat(20),
    topic: "test-markov",
    miningPath: 2,
    langs: ["en"],
    headline: "h",
    figures: ["f1", "f2"],
    sourceDescriptions: ["s"],
    links: [],
    analysis: {
      kind: "markov_lead",
      params: {
        asOfGame: 7,
        leader: "A",
        leaderPoints: 4.0,
        trailer: "B",
        trailerPoints: 3.5,
        games: [{ leaderColor: "White", winProb: 0.3, drawProb: 0.55, lossProb: 0.15 }],
        historicalBasis: "test",
      },
    },
  };
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
  const res = runAnalysis(spec, join(dir, "data.csv"), "2026-11-26T12:00:00.000Z");
  assert.ok(Math.abs(res.evidenceImpliedYes - 0.85) < 1e-9);
  rmSync(dir, { recursive: true, force: true });
});

test("verifySources: expect substrings must be present in scraped content", async () => {
  const cfg = { mode: "mock", liveSubmit: false } as unknown as AgentConfig;
  const firecrawl = createFirecrawl(cfg);
  const url = Object.keys(SCRAPE_FIXTURES)[0]!;
  const spec: ResearchSpec = {
    marketAddress: "0x" + "33".repeat(20),
    topic: "test-verify",
    miningPath: 3,
    langs: ["de"],
    headline: "h",
    figures: ["f1", "f2"],
    sourceDescriptions: ["s"],
    links: [
      { url, label: "l", lang: "de", access: "scraped", expect: ["VPI"] },
    ],
    analysis: { kind: "ballot_flag_snapshot", params: {} },
  };
  const ok = await verifySources(spec, firecrawl);
  assert.equal(ok.ok, true, JSON.stringify(ok.failures));
  const bad: ResearchSpec = {
    ...spec,
    links: [{ url, label: "l", lang: "de", access: "scraped", expect: ["NOT-PRESENT-STRING"] }],
  };
  const fail = await verifySources(bad, firecrawl);
  assert.equal(fail.ok, false);
  assert.equal(fail.failures[0]!.missing[0], "NOT-PRESENT-STRING");
});

test("submitter guard: mode=mock config can never enable liveSubmit", async () => {
  const { resolveConfig } = await import("../config.js");
  delete process.env.DELPHI_API_ACCESS_KEY;
  delete process.env.LIVE_SUBMIT;
  const cfg = resolveConfig({ mode: "mock", liveSubmit: true });
  assert.equal(cfg.liveSubmit, false);
  assert.equal(cfg.mode, "mock");
});

test("submitDraft refuses without the triple guard", async () => {
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
  writeFileSync(join(dir, "manifest.json"), "{}");
  const { submitDraft, SubmitGuardError } = await import("../submitter.js");
  const cfg = { mode: "live", liveSubmit: false } as unknown as AgentConfig;
  await assert.rejects(() => submitDraft(cfg, dir), SubmitGuardError);
  rmSync(dir, { recursive: true, force: true });
});

/** Shared types for the Agent Arena evidence-mining agent. */

/** Competition market as served by https://competition.delphi.fyi/markets.json */
export interface CompetitionMarket {
  address: string;
  question: string;
  delphiUrl: string;
  category: string;
  marketTier: string;
  wave: number;
  status: string;
  odds: { yes: number; no: number };
  closesAt: string;
  evidenceCutoffAt: string;
  pots: { judgement: string; settlement: string };
  resolutionCriteria: string;
}

/** Mirrors the SDK EntryState (kept local so mock mode needs no API). */
export interface EntryState {
  canSubmit: boolean;
  reason?: string;
  remainingOnMarket: number;
  /** USDC.e base units (6 decimals) left in the judgment pot. Information only. */
  judgementPotRemainingBaseUnits: string;
  restricted?: boolean;
  rateLimit: { resetAt: string };
}

/** Mirrors the SDK EvidenceLimits. */
export interface EvidenceLimits {
  submitsLeftThisHour: number;
  hourEndsAt: string;
  dailyCapLeft: number;
  dailyCapResetAt: string;
}

export interface EvidenceTerms {
  version: string;
  url: string;
  acceptedAt: string | null;
}

export interface SubmissionRecord {
  id: string;
  createdAt: string;
  agentId: string | null;
  note: string | null;
  links: string[];
  status: string;
  markets: { marketAddress: string; bounty: { amount: string; state: string } | null }[];
}

/** Read-only client surface used by the pipeline. Same shape in mock and live mode. */
export interface DelphiApi {
  readonly mode: "mock" | "live";
  getLimits(): Promise<EvidenceLimits>;
  getTerms(): Promise<EvidenceTerms>;
  getEntryState(marketAddress: string): Promise<EntryState>;
  listSubmissions(query: { market?: string }): Promise<SubmissionRecord[]>;
  listCompetitionMarkets(): Promise<CompetitionMarket[]>;
}

/** Mining path per the build brief: 1 arithmetic, 2 machine-readable trackers, 3 non-English scraping. */
export type MiningPath = 1 | 2 | 3;

export type AnalysisKind =
  | "cpi_base_effect"
  | "turnout_projection"
  | "poll_margin_regression"
  | "dhondt_seats"
  | "ballot_flag_snapshot"
  | "markov_lead"
  | "threshold_velocity"
  | "release_gap_cdf"
  | "blocker_clearance";

export type AnalysisSpec = { kind: AnalysisKind; params: Record<string, unknown> };

export type LinkAccess = "static-html" | "api-json" | "scraped";

export interface SourceLink {
  url: string;
  label: string;
  lang: string;
  access: LinkAccess;
  /** Substrings that the fetched source content must contain for the candidate to
   *  count as verifiable (anti-`unverifiable` gate). */
  expect?: string[];
}

/** Per-market research input. The mock runs read these as fixture data; live runs
 *  re-derive `analysis.params` and `figures` from the same sources before use. */
export interface ResearchSpec {
  marketAddress: string;
  topic: string;
  miningPath: MiningPath;
  langs: string[];
  /** Dated fact headline, figures inline. Must be novel (not a priced-in headline). */
  headline: string;
  /** Key figures pasted into the note so the judge never needs JS/rendered pages. */
  figures: string[];
  /** One line per link: what the page shows at fetch time. */
  sourceDescriptions: string[];
  links: SourceLink[];
  analysis: AnalysisSpec;
}

/** Result of the Python math/CSV generator for one spec. */
export interface AnalysisResult {
  kind: AnalysisKind;
  evidenceImpliedYes: number;
  confidence: "low" | "medium" | "high";
  methodLines: string[];
  figureSummary: string;
}

